const toolCall =
  message.toolCalls?.[0] ??
  message.toolCallList?.[0];
if (!toolCall?.id) {
  throw new Error('Vapi toolCallId is missing');
}
let args =
  toolCall.function?.arguments ??
  toolCall.arguments ??
  {};
if (typeof args === 'string') {
  args = JSON.parse(args);
}
const preference = String(args.preference ?? 'anytime').toLowerCase();
const requestedDay = String(args.requestedDay ?? '').trim();
const preferredTime = String(args.preferredTime ?? 'none').trim();

// requestedDay ko actual date mein convert karo
function resolveDate(requestedDay) {
  const now = new Date();
  const lower = requestedDay.toLowerCase();

  if (lower === 'today') return new Date(now);
  if (lower === 'tomorrow') {
    const d = new Date(now);
    d.setDate(d.getDate() + 1);
    return d;
  }

  const dayNames = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
  const dayIndex = dayNames.findIndex(d => lower.includes(d));
  if (dayIndex !== -1) {
    const currentDay = now.getDay();
    let daysAhead = dayIndex - currentDay;
    if (daysAhead <= 0) daysAhead += 7;
    const target = new Date(now);
    target.setDate(target.getDate() + daysAhead);
    return target;
  }

  const parsed = new Date(requestedDay);
  if (!isNaN(parsed.getTime())) return parsed;

  return now;
}

const targetDate = resolveDate(requestedDay);

const startOfDay = new Date(targetDate);
startOfDay.setHours(0, 0, 0, 0);

const endOfDay = new Date(targetDate);
endOfDay.setHours(23, 59, 59, 999);

return [
  {
    json: {
      toolCallId: toolCall.id,
      preference,
      requestedDay,
      preferredTime,
      startDate: Number(startOfDay.getTime()),
      endDate: Number(endOfDay.getTime()),
      startDateType: typeof startOfDay.getTime(),
      endDateType: typeof endOfDay.getTime()
    }
  }
];

