const ghlResponse = $input.first().json;
const vapiRequest = $('Extract Vapi Request').first().json;
const toolCallId = vapiRequest.toolCallId;
const preference = String(vapiRequest.preference ?? 'anytime').toLowerCase();
const requestedDay = String(vapiRequest.requestedDay ?? '').trim();
const TIMEZONE = 'America/Los_Angeles';

// requestedDay ko actual date string mein resolve karein
function resolveRequestedDate(requestedDay) {
  const now = new Date();
  const todayStr = new Intl.DateTimeFormat('en-CA', { timeZone: TIMEZONE }).format(now);
  const lower = requestedDay.toLowerCase().trim();

  if (lower === 'today') return todayStr;
  if (lower === 'tomorrow') {
    const tomorrow = new Date(now);
    tomorrow.setDate(tomorrow.getDate() + 1);
    return new Intl.DateTimeFormat('en-CA', { timeZone: TIMEZONE }).format(tomorrow);
  }

  // Day name check (monday, tuesday etc)
  const dayNames = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
  const dayIndex = dayNames.findIndex(d => lower.includes(d));
  if (dayIndex !== -1) {
    const currentDay = now.getDay();
    let daysAhead = dayIndex - currentDay;
    if (daysAhead <= 0) daysAhead += 7;
    const target = new Date(now);
    target.setDate(target.getDate() + daysAhead);
    return new Intl.DateTimeFormat('en-CA', { timeZone: TIMEZONE }).format(target);
  }

  // July 30, July 30th, 2026-07-30 format
  const parsed = new Date(requestedDay);
  if (!isNaN(parsed.getTime())) {
    return new Intl.DateTimeFormat('en-CA', { timeZone: TIMEZONE }).format(parsed);
  }

  return null;
}

const resolvedDate = resolveRequestedDate(requestedDay);

let allSlots = [];
for (const [key, value] of Object.entries(ghlResponse)) {
  if (key === 'traceId') continue;
  if (!value || !Array.isArray(value.slots)) continue;
  for (const slot of value.slots) {
    if (typeof slot === 'string' && !Number.isNaN(Date.parse(slot))) {
      allSlots.push(slot);
    }
  }
}

// Duplicate aur past slots remove
allSlots = [...new Set(allSlots)]
  .filter((slot) => Date.parse(slot) > Date.now())
  .sort((a, b) => Date.parse(a) - Date.parse(b));

// Requested day ke mutabiq filter
if (resolvedDate) {
  allSlots = allSlots.filter((slot) => slot.startsWith(resolvedDate));
}

function getLocalHour(iso) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIMEZONE,
    hour: 'numeric',
    hourCycle: 'h23',
  }).formatToParts(new Date(iso));
  const hourPart = parts.find((part) => part.type === 'hour');
  return Number(hourPart?.value);
}

// Preference filter
let preferredSlots = allSlots;
if (preference === 'morning') {
  preferredSlots = allSlots.filter((slot) => {
    const hour = getLocalHour(slot);
    return hour >= 8 && hour < 12;
  });
}
if (preference === 'afternoon') {
  preferredSlots = allSlots.filter((slot) => {
    const hour = getLocalHour(slot);
    return hour >= 12 && hour < 17;
  });
}

const combinedSlots = [
  ...preferredSlots,
  ...allSlots.filter((slot) => !preferredSlots.includes(slot)),
];
const selectedSlots = [...new Set(combinedSlots)].slice(0, 2);

function formatSpokenTime(iso) {
  return new Intl.DateTimeFormat('en-US', {
    timeZone: TIMEZONE,
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  }).format(new Date(iso));
}

let result;
if (selectedSlots.length === 0) {
  result = {
    success: false,
    requestedDate: resolvedDate ?? requestedDay,
    message: 'No appointment slots are currently available for the requested day.',
  };
} else {
  result = {
    success: true,
    requestedDate: resolvedDate ?? requestedDay,
    slots: selectedSlots.map((startTime, index) => ({
      option: index + 1,
      spokenTime: formatSpokenTime(startTime),
      startTime,
    })),
    instruction: 'Offer these options to the customer. Speak only spokenTime. Never speak startTime aloud.',
  };
}

return [
  {
    json: {
      toolCallId,
      resultText: JSON.stringify(result),
    },
  },
];

const payload = $json.body ?? $json;
const message = payload.message ?? {};
const toolCall =
  message.toolCalls?.[0] ??
  message.toolCallList?.[0];
if (!toolCall?.id) {
  throw new Error('Vapi toolCallId is missing');
}
let args =
  toolCall.function?.arguments ??
  toolCall.arguments ??
  {};
if (typeof args === 'string') {
  try {
    args = JSON.parse(args);
  } catch {
    throw new Error('Booking tool arguments are not valid JSON');
  }
}
const contactId = String(
  args.contactId ??
  args.contactID ??
  args.ghl_contact_id ??
  message.customer?.externalId ??
  message.call?.customer?.externalId ??
  ''
).trim();
const startTime = String(
  args.startTime ?? ''
).trim();
if (!contactId) {
  throw new Error(
    'GHL contactId is missing. Received arguments: ' +
    JSON.stringify(args)
  );
}
if (
  !startTime ||
  Number.isNaN(Date.parse(startTime))
) {
  throw new Error(
    'Valid appointment startTime is missing. Received arguments: ' +
    JSON.stringify(args)
  );
}
function addMinutesPreservingOffset(iso, minutes) {
  const newTimestamp =
    Date.parse(iso) + minutes * 60 * 1000;
  const offsetMatch =
    iso.match(/([+-])(\d{2}):(\d{2})$/);
  if (!offsetMatch) {
    return new Date(newTimestamp).toISOString();
  }
  const sign =
    offsetMatch[1] === '+' ? 1 : -1;
  const offsetMinutes =
    sign *
    (
      Number(offsetMatch[2]) * 60 +
      Number(offsetMatch[3])
    );
  const localTimestamp =
    newTimestamp +
    offsetMinutes * 60 * 1000;
  return (
    new Date(localTimestamp)
      .toISOString()
      .slice(0, 19) +
    offsetMatch[0]
  );
}
const endTime =
  addMinutesPreservingOffset(startTime, 30);

// Customer details from Vapi payload
const variableValues = payload.message?.artifact?.variableValues ?? payload.message?.call?.assistantOverrides?.variableValues ?? {};
const contactName = String(message.customer?.name ?? variableValues.full_name ?? '').trim();
const contactEmail = String(message.customer?.email ?? variableValues.email ?? '').trim();
const propertyAddress = String(variableValues.property_address ?? '').trim();

return [
  {
    json: {
      toolCallId: toolCall.id,
      contactId,
      startTime,
      endTime,
      contactName,
      contactEmail,
      propertyAddress
    }
  }
];

