const ghlResponse = $input.first().json;
const bookingRequest = $('Extract Booking Request').first().json;

const appointmentId =
  ghlResponse.id ??
  ghlResponse.appointment?.id ??
  ghlResponse.event?.id ??
  '';

const TIMEZONE = 'America/Los_Angeles';

const spokenTime = new Intl.DateTimeFormat('en-US', {
  timeZone: TIMEZONE,
  weekday: 'long',
  month: 'long',
  day: 'numeric',
  hour: 'numeric',
  minute: '2-digit',
  hour12: true
}).format(new Date(bookingRequest.startTime));

const result = {
  success: Boolean(appointmentId),
  appointmentId,
  spokenTime,
  message: appointmentId
    ? 'Appointment successfully created.'
    : 'Appointment response did not contain an appointment ID.'
};

return [
  {
    json: {
      toolCallId: bookingRequest.toolCallId,
      resultText: JSON.stringify(result),
      contactEmail: bookingRequest.contactEmail ?? '',
      contactName: bookingRequest.contactName ?? '',
      propertyAddress: bookingRequest.propertyAddress ?? '',
      spokenTime: spokenTime
    }
  }
];

const payload = $json.body ?? $json;
const message = payload.message ?? {};

const directCall =
  message.toolCalls?.[0] ??
  message.toolCallList?.[0];

const wrappedCall =
  message.toolWithToolCallList?.[0];

const toolCallId =
  directCall?.id ??
  wrappedCall?.toolCall?.id ??
  '';

const toolName =
  directCall?.function?.name ??
  directCall?.name ??
  wrappedCall?.toolCall?.function?.name ??
  wrappedCall?.function?.name ??
  wrappedCall?.name ??
  'unknown';

if (!toolCallId) {
  throw new Error(
    'Fallback request does not contain a Vapi toolCallId'
  );
}

const result = {
  success: false,
  toolName,
  message:
    'The requested scheduling action could not be processed. Do not claim success. Use the approved failure response.'
};

return [
  {
    json: {
      toolCallId,
      resultText: JSON.stringify(result)
    }
  }
];

const message =
  $json.body?.message ??
  $json.message ??
  {};

const toolName =
  message.toolCalls?.[0]?.function?.name ??
  message.toolCallList?.[0]?.function?.name ??
  message.toolWithToolCallList?.[0]?.function?.name ??
  message.toolWithToolCallList?.[0]?.name ??
  '';

if (!toolName) {
  throw new Error(
    'Vapi tool name not found. Payload: ' +
    JSON.stringify($json)
  );
}

return [
  {
    json: {
      ...$json,
      toolName
    }
  }
];

